testCases.expectedOutput:
BoundedContext CustomerManagement {
    domain {
        Aggregate Customer {
            customerId: UUID @identity
            fullName: String @required
            emailAddress: String @required @email
            phoneNumber: String?
            createdAt: DateTime @immutable
        }
    }
}

BoundedContext Shipping {
    domain {
        ValueObject Address {
            street: String @required
            city: String @required
            postalCode: String @maxLength(20)
            countryCode: String @minLength(2) @maxLength(2)
            apartment: String?
        }
    }
}

BoundedContext Catalog {
    domain {
        Entity Product {
            productId: UUID @identity
            name: String @required
            sku: String @unique
            price: Decimal @min(0)
            stock: Int @min(0)
            active: Boolean
        }
    }
}

BoundedContext Payments {
    domain {
        ValueObject Money {
            amount: Decimal @min(0)
            currency: String @required @maxLength(3)
        }
    }
}

BoundedContext Scheduling {
    domain {
        Aggregate Appointment {
            appointmentId: UUID @identity
            patientName: String @required
            scheduledAt: DateTime @required
            durationMinutes: Int @min(15) @max(240)
            notes: String?
        }
    }
}

BoundedContext Notifications {
    events {
        DomainEvent EmailQueued {
            eventId: UUID
            recipient: String @required @email
            subject: String @required
            queuedAt: DateTime @required
            retryCount: Int @min(0)
        }
    }
}

BoundedContext Catalog {
    domain {
        Aggregate Product {
            productId: UUID @identity
            name: String @required
            active: Boolean
        }
    }

    repositories {
        Repository ProductRepository for Product {
            findById(id: UUID): Product?
            findActive(): List<Product>
            save(product: Product): Void
        }
    }
}
